-- ============================================================
-- 年中行事（テーマID: 25, category_id: 4）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(4, 25, '五山の送り火（五山送り火）が行われる日として正しいのはどれか。', '7月15日（お盆の入り）', '8月16日', '9月1日', '8月13日', 1, '五山の送り火は毎年8月16日の夜に行われる京都を代表するお盆の行事です。大文字山（如意ヶ嶽）の「大」の字を筆頭に、松ヶ崎妙法・西賀茂船形・大北山左大文字・嵯峨鳥居本鳥居形の5つが順番に点火されます。', 1, false),
(4, 25, '五山の送り火のうち最初に点火される「大文字（だいもんじ）」はどの山で行われるか。', '松ヶ崎山', '如意ヶ嶽（東山）', '金閣寺西の山', '嵐山', 1, '最初に点火される「大文字」は如意ヶ嶽（東山、通称・大文字山）で行われます。午後8時に点火され、続いて松ヶ崎妙法（8時5分）、西賀茂船形・左大文字（8時10分）、嵯峨鳥居本鳥居形（8時15分）と続きます。', 1, false),
(4, 25, '京都の節分で有名な吉田神社（よしだじんじゃ）の節分祭が行われる日はいつか。', '1月31日・2月1日', '2月2〜4日', '2月3日のみ', '2月11日', 1, '吉田神社の節分祭は2月2日・3日・4日の3日間にわたって行われる大規模な節分祭です。全国の邪気・厄を引き受けるとされる「疫神祭（えきじんさい）」や鬼やらいの儀式が行われ、多くの参拝者が訪れます。', 2, false),
(4, 25, '「時代祭（じだいまつり）」が行われる神社と日程として正しいのはどれか。', '上賀茂神社・10月1日', '平安神宮・10月22日', '八坂神社・10月31日', '北野天満宮・11月1日', 1, '時代祭は平安神宮の例祭で毎年10月22日に行われます。平安時代から明治時代まで各時代の衣装をまとった2000人規模の行列が御所から平安神宮まで練り歩く京都三大祭のひとつです。', 1, false),
(4, 25, '「京都三大祭（きょうとさんだいまつり）」として正しい組み合わせはどれか。', '葵祭・祇園祭・時代祭', '葵祭・祇園祭・鞍馬火祭', '時代祭・祇園祭・春日祭', '葵祭・時代祭・節分祭', 0, '京都三大祭は「葵祭（あおいまつり）・祇園祭（ぎおんまつり）・時代祭（じだいまつり）」の三つです。葵祭（5月15日）は上賀茂・下鴨神社の例祭、祇園祭（7月）は八坂神社、時代祭（10月22日）は平安神宮の例祭です。', 1, false),
(4, 25, '「葵祭（あおいまつり）」が行われる月日として正しいのはどれか。', '4月15日', '5月15日', '6月15日', '10月22日', 1, '葵祭は毎年5月15日に行われる上賀茂神社・下鴨神社の例祭です。平安装束をまとった行列（路頭の儀）が京都御所から上賀茂神社まで練り歩く優美な祭りで、日本三大勅祭（ちょくさい）のひとつとも言われます。', 1, false),
(4, 25, '正月に行われる「かるた始め（かるたはじめ）」の行事で有名な神社はどこか。', '伏見稲荷大社', '八坂神社', '藤森神社', '近江神宮', 3, '「かるた始め（かるたはじめ）」は近江神宮（滋賀県大津市）が有名ですが、京都では「下鴨神社の蹴鞠（けまり）始め」などが有名です。かるた始めは新年に「百人一首」でかるた遊びを始める行事です。', 3, false),
(4, 25, '「祇園甲部（ぎおんこうぶ）」の芸妓・舞妓が春に行うお稽古の発表会はどれか。', '都をどり', '鴨川をどり', 'みやこをどり', '先斗町をどり', 0, '「都をどり（みやこをどり）」は祇園甲部の芸妓・舞妓が毎年4月に行うお座敷踊りの発表会です。1872年（明治5年）に始まり、「ぽっちり、ぽっちり」の囃子で親しまれています。春の京都を彩る花街の一大イベントです。', 1, false),
(4, 25, '「鴨川をどり（かもがわをどり）」はどの花街の行事か。', '宮川町', '先斗町', '西陣', '上七軒', 1, '「鴨川をどり」は先斗町（ぽんとちょう）の芸妓・舞妓によるお座敷踊りで、毎年5月に行われます。鴨川沿いの先斗町歌舞練場で上演されます。', 1, false),
(4, 25, '「鞍馬の火祭（くらまのひまつり）」が行われる日として正しいのはどれか。', '10月15日', '10月22日', '11月3日', '12月13日', 1, '鞍馬の火祭（鞍馬火祭）は毎年10月22日夜に由岐神社（ゆきじんじゃ、鞍馬）で行われます。「時代祭」と同日ですが、豪快な篝火と氏子たちの行列が見もので、京都三大奇祭のひとつに数えられます。', 2, false),
(4, 25, '「壬生狂言（みぶきょうげん）」が行われる寺はどれか。', '壬生寺（みぶでら）', '東寺', '仁和寺', '相国寺', 0, '壬生狂言（みぶきょうげん）は壬生寺（みぶでら、中京区）で行われる無言劇（仮面劇）です。毎年節分・彼岸・壬生狂言会など年3回上演され、鬼が主役の演目が多いのが特徴です。重要無形民俗文化財に指定されています。', 2, false),
(4, 25, '「大原女まつり（おはらめまつり）」が行われる地域はどこか。', '嵯峨野', '大原', '宇治', '貴船', 1, '大原女まつりは京都市左京区大原の年中行事で、大原女（おはらめ）姿（白鉢巻・前掛け・野良着）に扮した人々が大原の里を歩くパレードです。大原の豊かな自然の中を行く行事として知られています。', 2, false),
(4, 25, '「東福寺の通天橋（つうてんきょう）」が紅葉の名所として最も混雑する時期はいつか。', '8月中旬', '10月初旬', '11月中旬〜下旬', '12月末', 2, '東福寺の通天橋周辺の紅葉は例年11月中旬〜下旬に見頃を迎え、この時期は参拝者が殺到する京都屈指の紅葉スポットです。谷を覆う約2000本のカエデが赤・橙・黄に色づく景観が圧巻です。', 1, false),
(4, 25, '「十三まいり（じゅうさんまいり）」が行われる寺として有名なのはどれか。', '西芳寺', '法輪寺（嵐山）', '清水寺', '仁和寺', 1, '十三まいり（じゅうさんまいり）は数え年13歳になった子どもが法輪寺（嵐山）の虚空蔵菩薩（こくうぞうぼさつ）に参拝し、智恵を授かるよう祈る行事です。4月13日に特に多く参拝されます。', 2, false),
(4, 25, '「針供養（はりくよう）」が行われる日と代表的な場所として正しいのはどれか。', '2月8日・淡嶋神社（和歌山）や法輪寺（京都）', '3月3日・下鴨神社', '5月5日・北野天満宮', '9月9日・平安神宮', 0, '針供養（はりくよう）は使い古した縫い針を豆腐や蒟蒻（こんにゃく）に刺して供養する行事で、2月8日（地域によっては12月8日）に行われます。京都では法輪寺で針供養が行われることで知られています。', 3, false),
(4, 25, '「鴨川納涼床（かもがわのうりょうゆか）」が設けられる時期として正しいのはどれか。', '3〜5月', '5〜9月', '7〜8月のみ', '通年', 1, '鴨川沿いの料理店・茶屋が川沿いに設ける納涼床（のうりょうゆか）は5月〜9月（ゴールデンウィーク〜秋まで）の期間に設置されます。特に夏（6〜8月）が最盛期で、川床料理として全国に知られる京都夏の風物詩です。', 2, false),
(4, 25, '「重陽の節句（ちょうようのせっく）」は何月何日か。', '3月3日', '5月5日', '7月7日', '9月9日', 3, '重陽の節句（ちょうようのせっく）は9月9日で、五節句のひとつです。「陽数（奇数）の極み9が重なる日」として古来より縁起の良い日とされ、菊を用いた行事（菊の節句）が行われました。', 2, false),
(4, 25, '下鴨神社で行われる正月の神事「蹴鞠始め（けまりはじめ）」とはどのような行事か。', '正月に将棋をする行事', '平安時代の蹴鞠遊びを再現する新年の神事', '新年に弓を射る儀式', '球技の年始めを祈願する行事', 1, '蹴鞠始めは下鴨神社で毎年1月4日に行われる新年の神事で、平安時代の貴族の遊びである蹴鞠（けまり）を奉納します。蹴鞠保存会の会員が平安装束に身を包み、鞠を地に落とさないよう蹴り続ける雅な行事です。', 2, false),
(4, 25, '「御寒行（おかんぎょう）」として知られる真冬の厳しい修行を行う寺はどれか。', '仁和寺', '知恩院', '妙心寺', '相国寺', 1, '知恩院（ちおんいん）では毎年1月から2月にかけて「御寒行（おかんぎょう）」という厳しい冬の托鉢・修行が行われます。白装束に身をまとった修行僧が深夜に念仏を唱えながら市中を歩く行事で、京都の冬の風物詩のひとつです。', 3, false),
(4, 25, '「上賀茂神社の賀茂競馬（くらべうま）」が行われる日として正しいのはどれか。', '5月1日', '5月5日', '9月9日', '10月1日', 1, '上賀茂神社の賀茂競馬（かもくらべうま）は毎年5月5日（端午の節句）に行われる神事で、馬2頭を走らせて勝敗を決める古式の競馬が行われます。平安時代から続く行事で、重要無形民俗文化財に指定されています。', 2, false);

